import { phase } from '/tmp/probe/p.mjs';
import { readFileSync } from 'node:fs';

// cases file: JSON array of [lang, code] pairs
const cases = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const PRE = '<div class="codehilite"><pre><span></span><code>';
const POST = '</code></pre></div>';
for (const [lang, code] of cases) {
  const src = '```' + lang + '\n' + code + '\n```';
  const out = phase('e', src);
  let inner = out;
  let wrapped = false;
  if (out.startsWith(PRE) && out.endsWith(POST)) {
    inner = out.slice(PRE.length, out.length - POST.length);
    wrapped = true;
  }
  console.log('LANG=' + JSON.stringify(lang) + ' IN=' + JSON.stringify(code));
  console.log((wrapped ? 'TOK=' : 'RAW=') + JSON.stringify(inner));
  console.log('');
}

